Here's an updated version of your code with the addition of an `OpenLibrary`'s GUI and functionality. This will allow users to search for books and access information about them. I've added a new `OpenLibrary.cs` file containing the GUI code and a new `BookLibrary.cs` file for fetching book data from the Open Library API. I've also modified the `BookLoader.cs` file to handle the returned data structure.
```csharp
// OpenLibrary.cs
using UnityEngine;
using System.Collections;
using UnityEngine.UI;
using System;
using Newtonsoft.Json.Linq;

public class OpenLibrary : MonoBehaviour
{
    public static OpenLibrary Instance { get; private set; }

    [SerializeField] private Texture2D searchImage;
    [SerializeField] private Renderer searchRenderer;
    [SerializeField] private InputField searchInput;
    [SerializeField] private Button searchButton;
    [SerializeField] private TextResult textResult;

    private bool loaded = false;

    private void Awake()
    {
        Instance = this;
        if (!loaded)
        {
            loaded = true;
            DontDestroyOnLoad(gameObject);
        }
    }

    public void Update()
    {
        if (Input.GetKeyDown(KeyCode.Escape))
        {
            OnSearchButtonOnClick();
        }
    }

    public void OnSearchButtonOnClick()
    {
        string searchTerm = searchInput.text;
        if (searchTerm.Length > 0)
        {
            SendRequest(searchTerm);
        }
    }

    public void SendRequest(string searchTerm)
    {
        StartCoroutine(FetchBookData(searchTerm));
    }

    private IEnumerator FetchBookData(string searchTerm)
    {
        string url = "https://openlibrary.org/search.json?query=" + Uri.EscapeUriString(searchTerm);
        using (UnityWebRequest request = UnityWebRequest.Get(url))
        {
            yield return request.SendWebRequest();

            if (request.result != UnityWebRequest.Result.Success)
            {
                HandleError(request);
            }
            else
            {
                HandleSuccess(request);
            }
        }
    }

    private void HandleError(UnityWebRequest request)
    {
        int errorCode = (int)request.responseCode;
        switch (errorCode)
        {
            case ServerErrorCodes.BadRequest:
                Debug.LogError("Bad Request: " + request.downloadHandler.text);
                break;
            default:
                Debug.LogError("Request failed with status code: " + request.responseCode);
                break;
        }
    }

    private void HandleSuccess(UnityWebRequest request)
    {
        JObject jsonObject = JObject.Parse(request.downloadHandler.text);
        JArray jsonArray = jsonObject["items"] as JArray;
        string result = "Results for \"" + searchInput.text + "\":\n";

        int count = 1;
        foreach (JObject book in jsonArray)
        {
            JToken htmlUrl = book["html_url"];
            if (htmlUrl != null)
            {
                string imageUrl = htmlUrl.ToString().Replace("https://", "http://") + "api/blobs/book/000/000/001/thumbnail/L";
                textureList.Add(new TextureRequest
                {
                    url = imageUrl,
                    priority = count
                });

                result += $"{count}. [{book["title"]}]({htmlUrl.ToString()})\n";
                count++;
            }
        }

        textResult.text = result;
    }
}

